.guide-card { position: relative; display: flex; flex-direction: column; align-items: flex-start; gap: 12px; padding: 28px; background: #fff; border: 1px solid var(--border); border-radius: var(--r-lg); }
.guide-card p { color: var(--muted); }
.guide-card .link-btn { margin-top: auto; }
.guide-card-featured { border: 2px solid var(--navy); }
.guide-card-featured .badge { position: absolute; top: 20px; right: 20px; }
.guide-ic, .feature-ic { display: grid; place-items: center; width: 56px; height: 56px; border-radius: var(--r-lg); background: var(--panel); color: var(--navy); }

/* ---------- Product detail ---------- */
.pdp { padding: 8px 0 72px; }
.pdp-grid { display: grid; grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr); gap: 56px; align-items: start; }
.gallery { position: sticky; top: 104px; display: grid; gap: 12px; }
.gallery-main { position: relative; display: flex; flex-direction: column; background: var(--page); border-radius: 12px; padding: 32px 24px 12px; }
.gallery-badges { position: absolute; top: 20px; left: 20px; z-index: 2; }
.gallery-stage { display: grid; place-items: center; min-height: 0; }
.gallery-stage .visual { aspect-ratio: 1 / .9; }
.gallery-stage .book { width: 52cqw; }
.gallery-nav { display: flex; align-items: center; justify-content: center; gap: 12px; }
.spread { display: grid; grid-template-columns: 1fr 1fr; width: 88%; aspect-ratio: 1.45; background: #fff; border-radius: 4px; box-shadow: 0 18px 26px -18px rgba(11, 37, 69, .55); overflow: hidden; container-type: inline-size; margin-block: 4cqw; }
.spread-page { display: flex; flex-direction: column; gap: 2.4cqw; padding: 4cqw; }
.spread-page + .spread-page { border-left: 1px solid var(--border); background: linear-gradient(90deg, rgba(11, 37, 69, .05), transparent 12%); }
.sp-chapter { font-size: 2cqw; font-weight: 700; color: #3a7cb0; }
.sp-title { font-size: 3.4cqw; font-weight: 800; color: var(--navy); line-height: 1.15; }
.sp-lines { display: grid; gap: 1.4cqw; }
.sp-lines i { display: block; height: 1cqw; border-radius: 1cqw; background: var(--panel); }
.sp-lines i.short { width: 60%; }
.sp-box { display: grid; gap: 1.2cqw; padding: 2.4cqw; border-radius: 1cqw; background: var(--panel); }
.sp-box b { font-size: 2cqw; color: var(--navy); }
.sp-box i { display: block; height: 1cqw; border-radius: 1cqw; background: #fff; }
.sp-box i.short { width: 55%; }
.sp-scene { width: 100%; height: auto; border-radius: 1cqw; }
.sp-caption { font-size: 2.2cqw; font-weight: 700; color: var(--navy); }
.sample-page { display: flex; flex-direction: column; gap: 3cqw; width: 64%; aspect-ratio: 3 / 4; padding: 6cqw 5cqw; background: #fff; border-radius: 3px; box-shadow: 0 18px 26px -18px rgba(11, 37, 69, .55); container-type: inline-size; margin-block: 3cqw; }
.sample-page .sp-chapter { font-size: 4cqw; }
.sample-page .sp-title { font-size: 7cqw; }
.sample-page .sp-lines i { height: 2cqw; }
.sample-page .sp-lines { gap: 3cqw; }
.signs { display: grid; grid-template-columns: repeat(3, 1fr); gap: 5cqw; padding: 5cqw; border-radius: 2cqw; background: var(--page); justify-items: center; }
.sign { display: grid; place-items: center; width: 20cqw; aspect-ratio: 1; }
.sign i { font-style: normal; font-weight: 800; color: var(--navy); font-size: 6cqw; display: grid; place-items: center; }
.sign-round { border-radius: 50%; border: 3cqw solid #c0392b; background: #fff; }
.sign-blue { border: 0; background: #2d6db5; }
.sign-blue i { color: #fff; }
.sign-blue svg { width: 10cqw; height: 10cqw; stroke-width: 2.5; }
.sign-tri { clip-path: polygon(50% 4%, 98% 92%, 2% 92%); background: #c0392b; position: relative; }
.sign-tri::before { content: ""; position: absolute; inset: 0; clip-path: polygon(50% 22%, 84% 84%, 16% 84%); background: #fff; }
.sign-tri i { position: relative; margin-top: 4cqw; }
.sign-diamond { transform: rotate(45deg) scale(.78); background: #fff; border: 1.6cqw solid #fff; box-shadow: 0 0 0 .6cqw var(--control); }
.sign-diamond i { width: 70%; height: 70%; background: var(--yellow); }
.sign-stop { clip-path: polygon(30% 0, 70% 0, 100% 30%, 100% 70%, 70% 100%, 30% 100%, 0 70%, 0 30%); background: #c0392b; }
.sign-stop i { color: #fff; font-size: 4.4cqw; }
.sign-square { border-radius: 2cqw; background: #2d6db5; }
.sign-square i { color: #fff; font-size: 9cqw; }
.back-cover { display: flex; flex-direction: column; gap: 3cqw; width: 50%; aspect-ratio: 3 / 4; padding: 6cqw 5cqw; background: var(--navy); color: #fff; border-radius: 6px 2px 2px 6px; box-shadow: 0 18px 26px -18px rgba(11, 37, 69, .6); container-type: inline-size; margin-block: 3cqw; }
.bc-brand { font-size: 6cqw; font-weight: 700; }
.bc-brand b { color: var(--sky-light); }
.bc-title { font-size: 9cqw; font-weight: 800; line-height: 1.1; margin-top: 6cqw; }
.bc-list { display: grid; gap: 3cqw; font-size: 5.4cqw; margin-top: 4cqw; }
.bc-list span { display: flex; align-items: center; gap: 3cqw; }
.bc-list span::before { content: ""; width: 3.4cqw; height: 3.4cqw; border-radius: 50%; background: var(--yellow); flex: none; }
.bc-code { display: flex; gap: 1.4cqw; align-items: stretch; height: 12cqw; width: 50%; margin-top: auto; align-self: flex-end; padding: 2cqw; background: #fff; }
.bc-code i { flex: 1; background: var(--navy); }
.bc-code i:nth-child(3n) { flex: .4; }
.thumbs { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; }
.thumb { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 12px 8px; border-radius: var(--r-md); border: 1.5px solid var(--border); background: #fff; transition: border-color .15s; }
.thumb:hover { border-color: var(--sky-light); }
.thumb.is-active { border-color: var(--navy); box-shadow: inset 0 0 0 1px var(--navy); }
.thumb-art { display: grid; place-items: center; width: 40px; height: 40px; border-radius: var(--r-md); background: var(--panel); color: var(--navy); }
.thumb-cap { font-size: 12px; font-weight: 600; text-align: center; line-height: 1.3; }
.buybox { display: flex; flex-direction: column; align-items: flex-start; gap: 16px; padding-top: 8px; }
.buybox-meta { display: flex; flex-wrap: wrap; gap: 8px; }
.pdp-title { margin-top: -4px; }
.pdp-rating { display: inline-flex; align-items: center; gap: 8px; font-size: 15px; }
.pdp-rating:hover .muted { text-decoration: underline; }
.pdp-intro { font-size: 17px; line-height: 1.6; color: var(--muted); }
.pdp-price { display: flex; flex-wrap: wrap; align-items: baseline; gap: 6px 12px; padding-top: 8px; }
.pdp-price .price-note { flex-basis: 100%; }
.pdp-price .badge { align-self: center; }
.stock { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 8px; font-size: 15px; }
.stock-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--navy); box-shadow: 0 0 0 4px var(--panel); margin-right: 4px; }
.buy-row { display: flex; gap: 12px; width: 100%; }
.buy-btn { flex: 1; }
.qty { display: inline-grid; grid-template-columns: 48px 44px 48px; align-items: center; height: 48px; border: 1.5px solid var(--control); border-radius: var(--r-md); background: #fff; flex: none; }
.qty-btn { display: grid; place-items: center; height: 100%; color: var(--navy); border-radius: var(--r-md); }
.qty-btn:hover:not([disabled]) { background: var(--page); }
.qty-btn[disabled] { color: #b3bcc6; cursor: not-allowed; }
.qty-val { text-align: center; font-weight: 700; font-size: 17px; }
.qty-sm { grid-template-columns: 44px 36px 44px; height: 44px; }
.upsell-slot { width: 100%; }
.upsell { display: grid; grid-template-columns: 88px minmax(0, 1fr) auto; align-items: center; gap: 16px; width: 100%; padding: 12px 16px 12px 12px; border-radius: var(--r-lg); border: 1.5px dashed var(--sky-light); background: var(--page); transition: border-color .15s; }
.upsell:hover { border-color: var(--navy); }
.upsell-visual { display: block; border-radius: var(--r-md); background: #fff; }
.upsell-visual .visual { aspect-ratio: 1; }

